from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        kind = op[0]
        t = op[1]

        # purge expired entries
        expired_keys = [k for k, (v, wt) in cache.items() if wt + ttl <= t]
        for k in expired_keys:
            del cache[k]

        if kind == 'get':
            key = op[2]
            if key in cache:
                value, wt = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(-1)
        elif kind == 'put':
            key = op[2]
            value = op[3]
            if key in cache:
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)

    return results

